import Image from "next/image";

export default function Hero() {
  return (
    <section
      id="start"
      className="relative overflow-hidden border-b border-[#DED5C7] bg-[#F7F2E9] pt-20"
    >
      <div className="absolute inset-0 -z-10 bg-[radial-gradient(circle_at_top_left,#fffdf8_0%,#f7f2e9_48%,#efe6d9_100%)]" />

      <div className="mx-auto grid max-w-7xl items-center gap-10 px-6 py-10 lg:min-h-[610px] lg:grid-cols-[0.9fr_1.1fr] lg:px-8 lg:py-12">
        <div className="mx-auto max-w-xl text-center lg:mx-0 lg:text-left">
          <Image
            src="/images/brand/fio-logo.png"
            alt="Figuring It Out logo"
            width={145}
            height={145}
            priority
            className="mx-auto h-auto w-[115px] object-contain lg:mx-0 lg:w-[135px]"
          />

          <p className="mt-5 text-[11px] uppercase tracking-[0.42em] text-[#234531]">
            Figuring It Out™
          </p>

          <h1 className="mt-4 font-serif text-5xl leading-[0.98] text-[#5A2346] sm:text-6xl lg:text-[4.5rem]">
            Finding Clarity
            <span className="block">in the Chaos</span>
          </h1>

          <div className="mx-auto my-5 flex items-center justify-center gap-3 lg:mx-0 lg:justify-start">
            <span className="h-px w-14 bg-[#C89D4A]" />
            <span className="h-2 w-2 rotate-45 bg-[#C89D4A]" />
            <span className="h-px w-14 bg-[#C89D4A]" />
          </div>

          <p className="font-serif text-lg italic text-[#5A2346]">
            There isn&apos;t one right path.
          </p>

          <p className="mt-1 font-serif text-xl italic text-[#B77A24]">
            Only the one that&apos;s right for you.
          </p>

          <p className="mt-6 max-w-lg text-[15px] leading-7 text-[#33352F]">
            Figuring It Out™ is the lifelong practice of choosing to keep
            moving through uncertainty, trusting that understanding—and
            eventually confidence—will grow with every step.
          </p>

          <a
            href="#choose-your-path"
            className="mt-7 inline-flex items-center gap-3 rounded-sm bg-[#234531] px-6 py-3 text-xs uppercase tracking-[0.16em] text-white transition hover:bg-[#5A2346]"
          >
            Choose Your Path
            <span aria-hidden="true">↓</span>
          </a>
        </div>

        <div className="relative min-h-[400px] overflow-hidden rounded-t-[9rem] rounded-b-md border border-[#D5C5AE] shadow-[0_24px_65px_rgba(67,50,39,0.18)] sm:min-h-[480px] lg:min-h-[535px]">
          <Image
            src="/images/jenn-and-girls.jpg"
            alt="Jenn laughing with her daughters"
            fill
            priority
            sizes="(min-width: 1024px) 55vw, 100vw"
            className="object-cover object-center"
          />

          <div className="absolute inset-0 bg-gradient-to-t from-[#1D2D23]/45 via-transparent to-transparent" />

          <Image
            src="/images/brand/fio-logo.png"
            alt=""
            width={260}
            height={260}
            aria-hidden="true"
            className="absolute bottom-6 right-7 w-[140px] opacity-[0.12] brightness-0 invert"
          />
        </div>
      </div>

      <div className="border-t border-[#DED5C7] bg-[#FBF8F2] px-6 py-7 text-center">
        <p className="font-serif text-xl text-[#5A2346]">
          One philosophy. Two expressions. One purpose.
        </p>

        <p className="mx-auto mt-2 max-w-2xl text-sm leading-6 text-[#5E625B]">
          Helping people move from uncertainty to understanding—and find
          enough confidence to take the next step.
        </p>
      </div>
    </section>
  );
}