import Image from "next/image";

const links = [
  { label: "Start Here", href: "#start" },
  { label: "My Story", href: "#story" },
  { label: "The Book", href: "#book" },
  { label: "ODS Hourglass", href: "#ods-hourglass" },
  { label: "Resources", href: "#resources" },
  { label: "About", href: "#about" },
];

export default function Navbar() {
  return (
    <header className="fixed inset-x-0 top-0 z-50 border-b border-[#DED5C7] bg-[#F7F2E9]/95 backdrop-blur-md">
      <div className="mx-auto flex h-20 max-w-7xl items-center justify-between px-6 lg:px-8">
        <a href="#start" className="flex items-center gap-3">
          <Image
            src="/images/brand/fio-logo.png"
            alt="Figuring It Out"
            width={48}
            height={48}
            className="h-11 w-11 object-contain"
            priority
          />

          <div className="leading-tight">
            <p className="font-serif text-lg tracking-wide text-[#5A2346]">
              FIGURING IT OUT
            </p>

            <p className="mt-1 text-[9px] uppercase tracking-[0.32em] text-[#234531]">
              Jenn Kassan
            </p>
          </div>
        </a>

        <nav
          aria-label="Primary navigation"
          className="hidden items-center gap-7 text-[13px] text-[#234531] lg:flex"
        >
          {links.map((link) => (
            <a
              key={link.label}
              href={link.href}
              className="transition hover:text-[#B77A24]"
            >
              {link.label}
            </a>
          ))}
        </nav>

        <a
          href="#contact"
          className="hidden rounded-sm bg-[#234531] px-5 py-3 text-[11px] uppercase tracking-[0.14em] text-white transition hover:bg-[#5A2346] sm:inline-flex"
        >
          Let&apos;s Connect
        </a>
      </div>
    </header>
  );
}